const body = $input.first().json.body || $input.first().json;
const now = new Date().toISOString();

const normalized = {
  eventType: body.eventType || body.event_type || body.type || 'unknown',
  timestamp: body.timestamp || now,
  storeId: body.storeId || body.shop_id || body.shop || 'default_store',
  customerId: body.customerId || body.customer_id || (body.customer && body.customer.id) || null,
  orderId: body.orderId || body.order_id || (body.order && body.order.id) || null,
  productId: body.productId || body.product_id || (body.product && body.product.id) || null,
  cartId: body.cartId || body.cart_id || body.checkout_id || null,
  payload: body.payload || body,
  raw: body
};

return [{ json: normalized }];

const event = $input.first().json;
const et = (event.eventType || '').toLowerCase();

// Basic deterministic pre-routing hints + context keys needed
const contextNeeds = {
  abandoned_checkout: ['customer', 'cart', 'products', 'inventory', 'discount_history', 'previous_orders'],
  order_created: ['customer', 'order', 'products'],
  order_delayed: ['customer', 'order', 'tracking', 'order_value', 'history'],
  fulfillment_exception: ['customer', 'order', 'tracking', 'order_value', 'history'],
  return_requested: ['customer', 'order', 'product', 'return_history', 'reason'],
  inventory_low: ['product', 'inventory', 'sales_velocity', 'supplier'],
  customer_inactive: ['customer', 'last_order', 'order_frequency', 'favorites', 'aov'],
  customer_message: ['customer', 'message', 'history', 'products', 'inventory'],
  review_received: ['customer', 'order', 'product', 'review']
};

return [{
  json: {
    ...event,
    contextNeeds: contextNeeds[et] || ['customer', 'order'],
    preRouteHint: et
  }
}];

// Context Collector (MVP — uses payload data + placeholders for Shopify HTTP)
// In production, replace placeholders with real HTTP Request nodes using SHOPIFY_ADMIN_API credential
const item = $input.first().json;
const p = item.payload || {};
const event = item;

// Simulate / extract context from incoming payload (works with test data)
const context = {
  customer: p.customer || (event.customerId ? { id: event.customerId, name: p.customerName || 'Customer', email: p.email || null, previousOrders: p.previousOrders || 0, lifetimeValue: p.ltv || 0 } : null),
  cart: p.cart || (event.cartId ? { id: event.cartId, value: p.cartValue || p.total_price || 0, items: p.items || [] } : null),
  order: p.order || (event.orderId ? { id: event.orderId, value: p.orderValue || p.total_price || 0, status: p.status || 'unknown', createdAt: p.created_at || null } : null),
  product: p.product || (event.productId ? { id: event.productId, name: p.productName || 'Product', inventory: p.inventory || p.inventory_quantity || null } : null),
  inventory: p.inventory !== undefined ? { quantity: p.inventory, salesLast24h: p.salesLast24h || 0 } : null,
  tracking: p.tracking || p.fulfillment || null,
  returnReason: p.reason || p.return_reason || null,
  message: p.message || p.body || p.text || null,
  discountHistory: p.discountHistory || [],
  previousInteractions: p.previousInteractions || [],
  salesVelocity: p.salesLast24h || p.sales_velocity || 0
};

return [{
  json: {
    event: {
      eventType: event.eventType,
      timestamp: event.timestamp,
      storeId: event.storeId,
      customerId: event.customerId,
      orderId: event.orderId,
      productId: event.productId,
      cartId: event.cartId
    },
    context,
    rawPayload: p
  }
}];

const item = $input.first().json;
let text = item.text || item.output || item.response || JSON.stringify(item);

// Clean markdown fences if present
text = String(text).replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  // Retry repair attempt would go here in full version; fallback
  parsed = {
    agent: 'unsupported',
    priority: 'medium',
    reason: 'AI output parse failed — fallback to human review',
    confidence: 0.1
  };
}

const allowed = ['revenue_recovery','customer_intent','delivery_exception','inventory_rescue','returns_intelligence','winback'];
if (!allowed.includes(parsed.agent)) {
  parsed.agent = 'unsupported';
  parsed.reason = (parsed.reason || '') + ' | Invalid agent name';
}

return [{
  json: {
    ...($('Collect Context (Shopify-ready)').first().json),
    routing: parsed
  }
}];

const agentResult = $input.first().json;
const upstream = $('Parse & Validate AI Router Output').first().json;

const standardized = {
  agent: agentResult.agent || upstream.routing?.agent || 'unknown',
  decision: agentResult.decision || 'UNKNOWN',
  action: agentResult.action || '',
  confidence: agentResult.confidence || upstream.routing?.confidence || 0,
  reason: agentResult.reason || upstream.routing?.reason || '',
  customerId: agentResult.customerId || upstream.event?.customerId || '',
  orderId: agentResult.orderId || upstream.event?.orderId || '',
  status: agentResult.status || 'completed',
  timestamp: new Date().toISOString(),
  eventType: upstream.event?.eventType || '',
  channel: agentResult.channel || '',
  message: agentResult.message || '',
  escalate: agentResult.escalate || false,
  priority: agentResult.priority || upstream.routing?.priority || 'medium',
  result: agentResult
};

return [{ json: standardized }];

const upstream = $input.first().json;
return [{
  json: {
    agent: 'unsupported',
    decision: 'HUMAN_REVIEW',
    action: 'NO_ACTION',
    confidence: 0,
    reason: 'Event type not supported or routing failed',
    customerId: upstream.event?.customerId || '',
    orderId: upstream.event?.orderId || '',
    status: 'unsupported',
    timestamp: new Date().toISOString(),
    eventType: upstream.event?.eventType || 'unknown',
    escalate: true,
    priority: 'medium'
  }
}];
